import{_ as s,o as a,c as r,a2 as t}from"./chunks/framework.TaNiW7i8.js";const h=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),n={name:"guide/index.md"};function o(i,e,l,u,c,d){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Kessho est une application de bureau qui tient une <strong>mémoire structurée</strong> pour vos agents IA : un dossier de fichiers Markdown qui vous appartient. Une mémoire simple et plate, où l&#39;on empile des notes, grossit sans contrôle ; celle de Kessho est rangée en zones, en projets et en domaines, avec des résumés et des archives, pour que sa croissance reste maîtrisée. Vos agents IA la lisent et l&#39;enrichissent ; l&#39;application, elle, vous la montre, la range et vous laisse la modifier. Ce guide décrit l&#39;application, écran par écran.</p><p>Les captures d&#39;écran de ce guide montrent une mémoire de démonstration fictive.</p><h2 id="les-idees-a-connaitre" tabindex="-1">Les idées à connaître <a class="header-anchor" href="#les-idees-a-connaitre" aria-label="Permalink to &quot;Les idées à connaître&quot;">​</a></h2><p><strong>La mémoire.</strong> C&#39;est un simple dossier sur votre disque. Il est portable : vous pouvez le copier, le sauvegarder, l&#39;ouvrir avec d&#39;autres outils. Il est compatible avec Obsidian, sans en dépendre.</p><p><strong>Les notes.</strong> Chaque note est un fichier Markdown. Kessho les range dans des <strong>zones</strong>, qui disent à quoi sert une note : une session, un savoir, une procédure, un principe, un objectif, une personne… Voir <a href="/Kessho/guide/zones.html">Zones</a>.</p><p><strong>Les projets et les domaines.</strong> Une note se rattache à un projet ; un domaine est un périmètre transversal qui réunit plusieurs projets, et un projet peut appartenir à plusieurs domaines (voir <a href="/Kessho/guide/zones.html#le-domaine">Zones</a>). Chacun porte un résumé que vous pouvez donner à un agent pour reprendre le travail : ce sont les clés de contexte (voir <a href="/Kessho/guide/home.html">Accueil</a>).</p><p><strong>Les agents.</strong> Votre assistant IA parle à la mémoire par un serveur MCP, <code>kessho-mcp</code>, livré avec l&#39;application. Kessho le déclare dans les assistants installés sur votre poste (voir <a href="/Kessho/guide/agents.html">Connecter ses agents</a>). Ce que l&#39;agent écrit apparaît dans l&#39;application ; ce que vous modifiez dans l&#39;application, l&#39;agent le lit.</p><h2 id="par-ou-commencer" tabindex="-1">Par où commencer <a class="header-anchor" href="#par-ou-commencer" aria-label="Permalink to &quot;Par où commencer&quot;">​</a></h2><p><strong>Prise en main</strong></p><ol><li><a href="/Kessho/guide/first-run.html">Premier lancement</a> : l&#39;assistant en cinq étapes.</li><li><a href="/Kessho/guide/vault.html">Choisir sa mémoire</a> : où se trouve le dossier, et comment le changer.</li><li><a href="/Kessho/guide/agents.html">Connecter ses agents</a> : déclarer Kessho à vos assistants.</li></ol><p><strong>Écran par écran</strong></p><ul><li><a href="/Kessho/guide/home.html">Accueil</a> : l&#39;état de la mémoire d&#39;un coup d&#39;œil, et les clés de contexte.</li><li><a href="/Kessho/guide/zones.html">Zones</a> : parcourir, filtrer et ranger les notes.</li><li><a href="/Kessho/guide/atom.html">Atome et éditeur</a> : lire et écrire une note.</li><li><a href="/Kessho/guide/graph.html">Graphe</a> : voir les relations entre les notes.</li><li><a href="/Kessho/guide/sync.html">Synchronisation</a> : sauvegarder la mémoire avec git.</li><li><a href="/Kessho/guide/settings.html">Réglages</a> : apparence, mémoire, connecteurs.</li><li><a href="/Kessho/guide/help.html">Aide</a> : trouver de l&#39;aide dans l&#39;application.</li></ul><h2 id="et-avec-un-agent" tabindex="-1">Et avec un agent ? <a class="header-anchor" href="#et-avec-un-agent" aria-label="Permalink to &quot;Et avec un agent ?&quot;">​</a></h2><p>Ce guide parle de ce que vous faites avec la souris et le clavier. Pour ce que vous demandez à votre agent — reprendre une session, archiver, chercher —, voir <a href="/Kessho/agent/">Avec un agent</a>. Les outils eux-mêmes sont décrits dans la <a href="/Kessho/reference/mcp/">Référence MCP</a>.</p>',15)])])}const m=s(n,[["render",o]]);export{h as __pageData,m as default};
